import Foundation
import PetrelCore
import PetrelCrypto
import PetrelPLC
import Testing

/// Runs PetrelPLC over operations recorded from the public PLC directory.
///
/// Nothing in the vendored files is generated by Petrel: every operation,
/// CID, DID and signature was produced by other software (overwhelmingly
/// the reference TypeScript implementation) and accepted by
/// `plc.directory`. The vendored identities belong to organisations,
/// services and test scripts only; see `Vectors/plc-directory/README.md`
/// for the selection rule and for the shapes that are covered by synthetic
/// operations instead. The bulk run over arbitrary identities is
/// ``externalCorpus()``, which downloads nothing into the repository.
@Suite("PLC directory corpus")
struct PLCCorpusTests {
    struct Tally: Equatable {
        var operations = 0
        var legacyCreates = 0
        var regularGenesis = 0
        var updates = 0
        var tombstones = 0
        var k256Signatures = 0
        var p256Signatures = 0
    }

    /// Every vendored operation by CID, from the audit logs.
    private func operationsByCID() throws -> [String: PLCSignedOperation] {
        var operations = [String: PLCSignedOperation]()
        for did in try PLCVectors.auditLogDIDs {
            for entry in try PLCAuditLogVerifier.decode(PLCVectors.auditLogJSON(did: did), did: did) {
                operations[entry.cid] = entry.operation
            }
        }
        return operations
    }

    /// Verifies one export entry: the DID of a genesis operation, and the
    /// signature of every operation against the keys in force.
    private func verify(
        _ entry: PLCExportEntry,
        parents: [String: PLCSignedOperation],
        tally: inout Tally
    ) throws {
        tally.operations += 1
        if entry.operation.isTombstone { tally.tombstones += 1 }
        let authorizedKeys: [String]
        if let prev = entry.operation.prev {
            tally.updates += 1
            let parent = try #require(parents[prev], "parent \(prev) of \(entry.cid) is not in the corpus")
            // The parent is authenticated by content: its CID is the `prev`
            // the child signed.
            #expect(try parent.cid.string == prev)
            authorizedKeys = try #require(parent.rotationKeys, "\(entry.cid) follows a tombstone")
        } else {
            if entry.operation.legacyCreate != nil {
                tally.legacyCreates += 1
            } else {
                tally.regularGenesis += 1
            }
            #expect(try PLCOperationCodec.genesisDID(for: entry.operation) == entry.did)
            authorizedKeys = try #require(entry.operation.rotationKeys)
        }
        let signerIndex = try PLCOperationCodec.verify(
            entry.operation, authorizedRotationKeys: authorizedKeys
        )
        switch try ATProtoPublicKey(didKey: authorizedKeys[signerIndex]).curve {
        case .k256: tally.k256Signatures += 1
        case .p256: tally.p256Signatures += 1
        }
    }

    @Test("every vendored export line decodes, hashes to its CID and DID, and carries a valid signature")
    func exportLines() throws {
        let parents = try operationsByCID()
        // `exportEntries` throws on the first line that fails to decode or
        // whose CID does not match, so reaching the count means 100%.
        let legacy = try PLCVectors.exportEntries("export-legacy.jsonl")
        let sequenced = try PLCVectors.exportEntries("export-sequenced.jsonl")
        #expect(legacy.count == 34)
        #expect(sequenced.count == 14)

        // The legacy file holds every operation of every vendored audit log.
        #expect(Set(legacy.map(\.cid)) == Set(parents.keys))
        var tally = Tally()
        for entry in legacy {
            try verify(entry, parents: parents, tally: &tally)
            #expect(parents[entry.cid] == entry.operation)
        }
        #expect(tally == Tally(
            operations: 34,
            legacyCreates: 2,
            regularGenesis: 10,
            updates: 22,
            tombstones: 3,
            k256Signatures: 32,
            p256Signatures: 2
        ))

        // The sequenced file holds some of the same operations again.
        var sequencedTally = Tally()
        for entry in sequenced {
            try verify(entry, parents: parents, tally: &sequencedTally)
            #expect(parents[entry.cid] == entry.operation)
        }
        #expect(sequencedTally.operations == 14)
        #expect(sequencedTally.k256Signatures == 14)
    }

    @Test("the sequenced and legacy export formats are both read")
    func exportFormats() throws {
        let sequenced = try PLCVectors.exportEntries("export-sequenced.jsonl")
        #expect(sequenced.allSatisfy { $0.sequence != nil && $0.nullified == nil })
        // bsky.app's genesis operation was the 26,043rd the directory accepted.
        #expect(sequenced.first?.did == PLCVectors.Organisation.bskyApp)
        #expect(sequenced.first?.cursor == .sequence(26_043))
        // Within one identity, sequence order is log order.
        let support = sequenced.filter { $0.did == PLCVectors.Organisation.support }
        #expect(support.count == 4)
        #expect(zip(support, support.dropFirst()).allSatisfy { ($0.sequence ?? 0) < ($1.sequence ?? 0) })
        #expect(support.first?.operation.legacyCreate != nil)

        let legacy = try PLCVectors.exportEntries("export-legacy.jsonl")
        #expect(legacy.allSatisfy { $0.sequence == nil && $0.nullified != nil })
        #expect(legacy.first.map { $0.cursor } == legacy.first.map { .timestamp($0.createdAt) })
        // The legacy format carries the directory's nullified flag: the two
        // tombstones that were displaced by a recovery.
        let nullified = legacy.filter { $0.nullified == true }
        #expect(nullified.count == 2)
        #expect(nullified.allSatisfy { $0.operation.isTombstone })

        // The same operation is the same in both formats.
        let legacyByCID = Dictionary(uniqueKeysWithValues: legacy.map { ($0.cid, $0) })
        for entry in sequenced {
            let other = try #require(legacyByCID[entry.cid])
            #expect(other.operation == entry.operation)
            #expect(other.createdAt == entry.createdAt)
        }
    }

    @Test("every vendored audit log verifies end to end")
    func auditLogs() throws {
        let dids = try PLCVectors.auditLogDIDs
        #expect(dids.count == 12)
        var operations = 0
        var curves = Set<ATProtoKeyCurve>()
        for did in dids {
            let log = try PLCAuditLogVerifier.verify(json: PLCVectors.auditLogJSON(did: did), did: did)
            operations += log.entries.count
            #expect(log.signers.count == log.entries.count)
            for signer in log.signers {
                try curves.insert(ATProtoPublicKey(didKey: signer).curve)
            }
            // The directory's own flags agree with what was recomputed.
            let claimed = try PLCAuditLogVerifier.decode(PLCVectors.auditLogJSON(did: did), did: did)
            #expect(claimed.map(\.nullified) == log.entries.map(\.nullified), "\(did)")
            // The linear log, as `GET /:did/log` returns it, verifies to the
            // same state.
            let linear = try PLCAuditLogVerifier.validateOperationLog(
                log.activeEntries.map(\.operation), did: did
            )
            #expect(linear == log.documentData, "\(did)")
        }
        #expect(operations == 34)
        #expect(curves == [.k256, .p256])
    }

    @Test("a legacy create genesis is read, hashed in its own format and normalized")
    func legacyGenesis() throws {
        // support.bsky.team was registered in January 2023, before the
        // operation format changed.
        let did = PLCVectors.Organisation.support
        let log = try PLCAuditLogVerifier.verify(json: PLCVectors.auditLogJSON(did: did), did: did)
        let genesis = try #require(log.entries.first?.operation.legacyCreate)
        #expect(genesis.handle == "support-team.bsky.social")
        #expect(genesis.service == "https://bsky.social")
        #expect(try PLCOperationCodec.genesisDID(for: log.entries[0].operation) == did)

        // Normalized the way the reference `normalizeOp` does.
        #expect(genesis.rotationKeys == [genesis.recoveryKey, genesis.signingKey])
        #expect(genesis.verificationMethods == ["atproto": genesis.signingKey])
        #expect(genesis.alsoKnownAs == ["at://support-team.bsky.social"])
        #expect(genesis.services == [
            "atproto_pds": PLCService(type: "AtprotoPersonalDataServer", endpoint: "https://bsky.social"),
        ])

        // The update that follows the legacy genesis names its CID and is
        // signed by one of its two keys.
        #expect(log.entries.count == 4)
        #expect(try log.entries[1].operation.prev == log.entries[0].operation.cid.string)
        #expect(genesis.rotationKeys.contains(log.signers[1]))
        #expect(log.documentData?.handle == "support.bsky.team")

        // JSON round trip keeps the legacy shape byte for byte in DAG-CBOR.
        let reencoded = try PLCOperationCodec.decodeSignedJSON(log.entries[0].operation.canonicalJSON)
        #expect(reencoded == log.entries[0].operation)
        #expect(try reencoded.cid.string == log.entries[0].cid)

        // The deprecated format may be read forever and written never.
        #expect(throws: PetrelPLCError.self) {
            try PLCOperationCodec.validateForSubmission(log.entries[0].operation)
        }
    }

    @Test("a legacy service without a scheme is normalized with https://, and legacy keys may be P-256")
    func legacyServiceWithoutScheme() throws {
        let did = PLCVectors.TestIdentity.legacyP256
        let log = try PLCAuditLogVerifier.verify(json: PLCVectors.auditLogJSON(did: did), did: did)
        let genesis = try #require(log.head.operation.legacyCreate)
        #expect(genesis.service == "localhost:4989")
        #expect(log.documentData?.pdsEndpoint == "https://localhost:4989")
        #expect(try ATProtoPublicKey(didKey: log.signers[0]).curve == .p256)
    }

    @Test("a tombstoned identity verifies and has no state")
    func tombstone() throws {
        let did = PLCVectors.TestIdentity.tombstoned
        let log = try PLCAuditLogVerifier.verify(json: PLCVectors.auditLogJSON(did: did), did: did)
        #expect(log.entries.count == 2)
        #expect(log.isTombstoned)
        #expect(log.head.operation.isTombstone)
        #expect(log.documentData == nil)
        #expect(try log.head.operation.prev == log.entries[0].operation.cid.string)
        #expect(try PLCAuditLogVerifier.validateOperationLog(log.entries.map(\.operation), did: did) == nil)
    }

    @Test("a real recovery: a tombstone nullified by the higher-authority rotation key")
    func recovery() throws {
        for did in [PLCVectors.TestIdentity.recovered, PLCVectors.TestIdentity.recoveredAgain] {
            let json = try PLCVectors.auditLogJSON(did: did)
            let log = try PLCAuditLogVerifier.verify(json: json, did: did)
            // genesis, update, tombstone (nullified), recovery.
            #expect(log.entries.map(\.nullified) == [false, false, true, false])
            #expect(log.entries[2].operation.isTombstone)
            #expect(!log.isTombstoned)
            #expect(log.activeEntries.count == 3)
            // The tombstone and the recovery fork from the same operation…
            #expect(log.entries[2].operation.prev == log.entries[1].cid)
            #expect(log.entries[3].operation.prev == log.entries[1].cid)
            // …the tombstone signed by the second rotation key, the recovery
            // by the first.
            let keys = try #require(log.entries[1].operation.rotationKeys)
            #expect(keys.count == 2)
            #expect(log.signers[2] == keys[1])
            #expect(log.signers[3] == keys[0])
            #expect(try PLCOperationCodec.verify(log.entries[2].operation, authorizedRotationKeys: keys) == 1)
            #expect(try PLCOperationCodec.verify(log.entries[3].operation, authorizedRotationKeys: keys) == 0)

            // Nullification is derived, not read: with the directory's flags
            // cleared the result is the same…
            let claimed = try PLCAuditLogVerifier.decode(json, did: did)
            #expect(claimed.map(\.nullified) == [false, false, true, false])
            let cleared = claimed.map {
                PLCAuditEntry(did: $0.did, operation: $0.operation, cid: $0.cid, nullified: false, createdAt: $0.createdAt)
            }
            #expect(try PLCAuditLogVerifier.verify(cleared, did: did) == log)

            // …and the same operations dated outside the window are refused.
            var late = cleared
            late[3] = PLCAuditEntry(
                did: did, operation: cleared[3].operation, cid: cleared[3].cid,
                nullified: false, createdAt: "2024-08-01T00:00:00.000Z"
            )
            #expect(throws: PetrelPLCError.unauthorized("PLC recovery exceeds the 72-hour window")) {
                try PLCAuditLogVerifier.verify(late, did: did)
            }
            // The currently valid operations form a linear log.
            #expect(try PLCAuditLogVerifier.validateOperationLog(
                log.activeEntries.map(\.operation), did: did
            ) == log.documentData)
        }
    }

    @Test("real operations outside the atproto account shape are read")
    func unusualShapes() throws {
        // No verification methods and no handle: a repository identity
        // registered by a service. Allowed for reading and for writing.
        let knot = PLCVectors.Organisation.tangledKnotRepository
        var log = try PLCAuditLogVerifier.verify(json: PLCVectors.auditLogJSON(did: knot), did: knot)
        let first = try #require(log.entries.first?.operation.regular)
        #expect(first.verificationMethods.isEmpty)
        #expect(first.alsoKnownAs.isEmpty)
        #expect(first.services["tangled_knot"] != nil)
        try PLCOperationCodec.validateForSubmission(log.entries[0].operation)

        // Several verification methods and services: a labeler.
        let labeler = PLCVectors.Organisation.moderation
        log = try PLCAuditLogVerifier.verify(json: PLCVectors.auditLogJSON(did: labeler), did: labeler)
        let state = try #require(log.documentData)
        #expect(Set(state.verificationMethods.keys) == ["atproto", "atproto_label"])
        #expect(state.services["atproto_labeler"]?.type == "AtprotoLabeler")
        #expect(state.handle == "moderation.bsky.app")
        let document = PLCDIDDocument(data: state)
        #expect(document.verificationMethod.map(\.id) == ["\(labeler)#atproto", "\(labeler)#atproto_label"])
        #expect(document.service.map(\.id) == ["#atproto_labeler", "#atproto_pds"])

        // A 7 kB alias, signed with a P-256 key: inside the specification's
        // 7,500-byte limit, outside the reference server's current 4,000.
        let large = PLCVectors.TestIdentity.large
        log = try PLCAuditLogVerifier.verify(json: PLCVectors.auditLogJSON(did: large), did: large)
        let size = try log.head.operation.canonicalDAGCBOR.count
        #expect(size > 4_000 && size <= 7_500)
        #expect(try ATProtoPublicKey(didKey: log.signers[0]).curve == .p256)
        #expect(throws: PetrelPLCError.self) {
            try PLCOperationCodec.validateForSubmission(log.head.operation, limits: .referenceDirectory)
        }
    }

    /// Runs the same checks over a directory of export pages that is not
    /// part of the repository: arbitrary identities, in bulk. Fill a
    /// directory with `Vectors/plc-directory/fetch-export-sample.sh` and
    /// point `PETREL_PLC_CORPUS_DIR` at it.
    @Test(
        "an external export sample decodes without a single rejection",
        .enabled(if: ProcessInfo.processInfo.environment["PETREL_PLC_CORPUS_DIR"] != nil)
    )
    func externalCorpus() throws {
        let directory = try URL(fileURLWithPath: #require(
            ProcessInfo.processInfo.environment["PETREL_PLC_CORPUS_DIR"]
        ))
        let files = try FileManager.default.contentsOfDirectory(atPath: directory.path)
            .filter { $0.hasSuffix(".jsonl") }.sorted()
        var lines = 0
        var rejected = [String]()
        var genesisVerified = 0
        var updatesVerified = 0
        var seen = [String: PLCSignedOperation]()
        var curves = [ATProtoKeyCurve: Int]()
        for file in files {
            let data = try Data(contentsOf: directory.appendingPathComponent(file))
            for line in data.split(separator: UInt8(ascii: "\n")) where !line.isEmpty {
                lines += 1
                do {
                    let entry = try PLCExportEntry(jsonLine: Data(line))
                    var keys: [String]?
                    if entry.operation.prev == nil, !entry.operation.isTombstone {
                        try PLCOperationCodec.verifyGenesis(entry.operation, expectedDID: entry.did)
                        keys = entry.operation.rotationKeys
                        genesisVerified += 1
                    } else if let prev = entry.operation.prev, let parent = seen[prev] {
                        keys = parent.rotationKeys
                        updatesVerified += 1
                    }
                    if let keys {
                        let index = try PLCOperationCodec.verify(entry.operation, authorizedRotationKeys: keys)
                        try curves[ATProtoPublicKey(didKey: keys[index]).curve, default: 0] += 1
                    }
                    seen[entry.cid] = entry.operation
                } catch {
                    rejected.append("\(file): \(error)")
                }
            }
        }
        print(
            "PLC external corpus: files=\(files.count) lines=\(lines) rejected=\(rejected.count) "
                + "genesisVerified=\(genesisVerified) updatesVerified=\(updatesVerified) "
                + "k256=\(curves[.k256] ?? 0) p256=\(curves[.p256] ?? 0)"
        )
        #expect(lines > 0)
        #expect(rejected.isEmpty, "\(rejected.prefix(5))")
    }
}
